1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Locale;
5	import java.util.Set;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns the unified {@code memberId} formatted {@code <REGION><FY><HASH8><CHK>}, where REGION is the
13	 * region code derived from the owner's postcode (see {@link Locality}, which prefers the postcode's
14	 * range, falling back to the city table and finally {@code "UNKNOWN"}); FY is the two-digit fiscal
15	 * year (starting 1 July) of the business-day-adjusted {@code registrationDate}; HASH8 is the first 8
16	 * upper-case hex characters of SHA-256 over the normalized telephone concatenated with the last name
17	 * (the same region-and-hash identity as before); and CHK is a single Luhn check digit computed over
18	 * the decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D5}). The telephone has
19	 * already been normalized to E.164 form by {@link NormalizeTelephone} earlier in the pipeline, so the
20	 * stored value is used directly.
21	 * <p>
22	 * When the computed member id collides with an existing owner's {@code memberId}, {@code -<n>} is
23	 * appended with the smallest {@code n} of 2 or more that makes it unique (e.g.
24	 * {@code NSW261A2B3C4D5-2}). Runs before the owner is saved, so {@link OwnerRepository#findAll()}
25	 * sees only the owners that existed before this create.
26	 */
27	public class AssignMemberId {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String region = Locality.of(owner.getCity(), owner.getPostcode());
31	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
32	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
33	        String hash8 = Sha256.hex(telephone + lastName).substring(0, 8).toUpperCase(Locale.ROOT);
34	        String fy = String.format("%02d", FiscalYear.yy(owner.getRegistrationDate()));
35	        String core = region + fy + hash8;
36	        String base = core + CheckDigit.of(core);
37	
38	        Set<String> existing = new HashSet<>();
39	        for (Owner other : ownerRepository.findAll()) {
40	            if (other.getMemberId() != null) {
41	                existing.add(other.getMemberId());
42	            }
43	        }
44	
45	        String memberId = base;
46	        for (int n = 2; existing.contains(memberId); n++) {
47	            memberId = base + "-" + n;
48	        }
49	        owner.setMemberId(memberId);
50	    }
51	}
52

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	/**
6	 * Derives an owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} and always one of
7	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
8	 * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3 or more,
9	 * otherwise {@code STANDARD}. AREA is {@code METRO} when the locality is a known region
10	 * (NSW, VIC or QLD, see {@link Locality}), otherwise {@code REGIONAL}. Pinned and stable across
11	 * requests, so it needs no persisted column.
12	 */
13	public final class OwnerSegment {
14	
15	    /** Membership level at or above which the owner is in the PREMIUM tier. */
16	    private static final int PREMIUM_THRESHOLD = 3;
17	
18	    /** Regions treated as METRO; anything else (including "UNKNOWN") is REGIONAL. */
19	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
20	
21	    private OwnerSegment() {
22	    }
23	
24	    /** The segment for the given {@code locality} region and {@code membershipLevel}. */
25	    public static String of(String locality, Integer membershipLevel) {
26	        String tier = membershipLevel != null && membershipLevel >= PREMIUM_THRESHOLD ? "PREMIUM" : "STANDARD";
27	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
28	        return tier + "_" + area;
29	    }
30	}
