4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	
6	/** identity-v2: apiVersion is 2, the memberId/identityKey/householdId are grouped under a nested
7	 * 'identity' object, and those three are no longer at the top level. Exact structural contract. */
8	class AcceptanceTest extends AcceptanceBase {
9	
10		@Test
11		void coreV2GroupsIdentityAndVersions() throws Exception {
12			int id = createOwnerOk(structuredOwner());
13			getOwner(id).andExpect(jsonPath("$.apiVersion").value(2))
14					.andExpect(jsonPath("$.identity.memberId").isNotEmpty())
15					.andExpect(jsonPath("$.identity.identityKey").isNotEmpty())
16					.andExpect(jsonPath("$.identity.householdId").isNotEmpty())
