2	
3	/**
4	 * Computes the Luhn check digit (0-9) over the decimal digits contained in a string. Non-digit
5	 * characters (region letters and the hex letters {@code A-F} of the hash) are ignored. Used to
6	 * produce the {@code CHK} segment of the {@code memberId}, taken over the decimal digits of the
7	 * {@code <REGION><FY><HASH8>} core (see {@link AssignMemberId}).
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    /** The Luhn check digit over the digits of {@code s}, or 0 when {@code s} is null. */
15	    public static int of(String s) {
16	        if (s == null) {
17	            return 0;
18	        }
19	        int sum = 0;
20	        boolean dbl = true;
21	        for (int i = s.length() - 1; i >= 0; i--) {
22	            char c = s.charAt(i);
23	            if (c < '0' || c > '9') {
24	                continue;
25	            }
26	            int d = c - '0';
27	            if (dbl) {
28	                d *= 2;
29	                if (d > 9) {
30	                    d -= 9;
31	                }
32	            }
33	            sum += d;
34	            dbl = !dbl;
35	        }
36	        return (10 - (sum % 10)) % 10;
37	    }
38	}
