1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * American Soundex of a name — the phonetic code the owner identity now hashes over (see
5	 * {@link IdentityKey}) and the soft-match ({@link DetectPossibleDuplicate}) groups by. The code is the
6	 * first letter followed by three digits derived from the remaining consonants (b,f,p,v→1;
7	 * c,g,j,k,q,s,x,z→2; d,t→3; l→4; m,n→5; r→6), where adjacent letters with the same digit — including a
8	 * pair separated only by {@code h}/{@code w} — collapse to one, vowels (and {@code y}) reset the run,
9	 * and the result is zero-padded or truncated to four characters. Non-letters are dropped first; a
10	 * value with no letters yields an empty string. Deterministic, so both the create-time duplicate check
11	 * and the mapped response derive the identical value.
12	 */
13	public final class Soundex {
14	
15	    /** A–Z → Soundex digit; '0' marks vowels and the ignored {@code h}/{@code w}. */
16	    private static final char[] MAP = "01230120022455012623010202".toCharArray();
17	
18	    private Soundex() {
19	    }
20	
21	    public static String of(String value) {
22	        if (value == null) {
23	            return "";
24	        }
25	        StringBuilder letters = new StringBuilder();
26	        for (int i = 0; i < value.length(); i++) {
27	            char c = Character.toUpperCase(value.charAt(i));
28	            if (c >= 'A' && c <= 'Z') {
29	                letters.append(c);
30	            }
31	        }
32	        if (letters.length() == 0) {
33	            return "";
34	        }
35	        char first = letters.charAt(0);
36	        StringBuilder code = new StringBuilder();
37	        code.append(first);
38	        char last = MAP[first - 'A'];
39	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
40	            char ch = letters.charAt(i);
41	            if (ch == 'H' || ch == 'W') {
42	                continue; // ignored: does not break a run of same-coded consonants
43	            }
44	            char digit = MAP[ch - 'A'];
45	            if (digit != '0' && digit != last) {
46	                code.append(digit);
47	            }
48	            last = digit; // vowels reset the run so later same-coded consonants still count
49	        }
50	        while (code.length() < 4) {
51	            code.append('0');
52	        }
53	        return code.toString();
54	    }
55	}
